t("*squeak*", "*squeak*", "_t")
t("Squeak!", "¡Squeak!", "_t")
t("Squeak??", "¿Squeak?", "_t")
t("SQUEAK!!!!!", "¡SQUEAK!!", "_t")
t("ghoulish rat", "rata gruñida", "entity name")
